// Did you know there is a limit to how big of a number you
// can represent in JavaScript when writing ?

const maxHighValue = 9007199254740991;
const maxLowValue = -9007199254740991;

// If you go one over/below these numbers
// then you start to get into dangerous territory.

const oneOverMax = 9007199254740992;
const oneBelowMin = -9007199254740992;

// The solution for handling numbers of this size
// is to convert these numbers to BigInts instead
// of a number:
//
// https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/BigInt

// TypeScript will now offer a fixit for number
// literals which are above 2^52 (positive / negative)
// which adds the suffix "n" which informs JavaScript
// that the type should be BigInt.

// Number literals
9007199254740993;
-9007199254740993;
9007199254740994;
-9007199254740994;

// Hex numbers
0x19999999999999;
-0x19999999999999;
0x20000000000000;
-0x20000000000000;
0x20000000000001;
-0x20000000000001;

// New to 3.7 is the ability to quickly convert
// a const variable to a let when the value
// has been re-assigned.

// You can try this by highlighting the below error
// and choosing to run the quick-fix.

const displayName = "Andrew";

displayName = "Andrea";

// With 3.7 TypeScript's existing 'infer from usage'
// code fix became smarter. It will now use a list of
// known important types (string, number, array, Promise)
// and infer whether the usage of a type matches the API
// of these objects.

// For the next few examples, select the parameters of
// the functions, click the light bulb and choose
// "Infer Parameter types..."

// Infer a number array:

function pushNumber(arr) {
  arr.push(12);
}

// Infer a promise:

function awaitPromise(promise) {
  promise.then((value) => console.log(value));
}

// Infer the function, and its return type:

function inferAny(app) {
  const result = app.use("hi");
  return result;
}

// Infer a string array because a string
// was added to it:

function insertString(names) {
  names[1] = "hello";
}

// TypeScript's error messages can sometimes be a tad verbose...
// With 3.7, we've taken a few cases which could be particularly
// egregious.

// Nested Properties

let a = { b: { c: { d: { e: "string" } } } };
let b = { b: { c: { d: { e: 12 } } } };

a = b;

// Before, it was 2 lines of code per nested property, which
// quickly meant people learned to read error messages by
// reading the first and then last line of an error message.

// Now they're inline. :tada:

// Previously in 3.6:
//
// Type '{ b: { c: { d: { e: number; }; }; }; }' is not assignable to type '{ b: { c: { d: { e: string; }; }; }; }'.
//   Types of property 'b' are incompatible.
//     Type '{ c: { d: { e: number; }; }; }' is not assignable to type '{ c: { d: { e: string; }; }; }'.
//       Types of property 'c' are incompatible.
//         Type '{ d: { e: number; }; }' is not assignable to type '{ d: { e: string; }; }'.
//           Types of property 'd' are incompatible.
//             Type '{ e: number; }' is not assignable to type '{ e: string; }'.
//               Types of property 'e' are incompatible.
//                 Type 'number' is not assignable to type 'string'

// This can handle working through different types of objects,
// to still give a useful and concise error message.

class ExampleClass {
  state = "ok";
}

class OtherClass {
  state = 12;
}

let x = { a: { b: { c: { d: { e: { f: ExampleClass } } } } } };
let y = { a: { b: { c: { d: { e: { f: OtherClass } } } } } };
x = y;

// Previously in 3.6:
//
// Type '{ a: { b: { c: { d: { e: { f: typeof OtherClass; }; }; }; }; }; }' is not assignable to type '{ a: { b: { c: { d: { e: { f: typeof ExampleClass; }; }; }; }; }; }'.
//   Types of property 'a' are incompatible.
//     Type '{ b: { c: { d: { e: { f: typeof OtherClass; }; }; }; }; }' is not assignable to type '{ b: { c: { d: { e: { f: typeof ExampleClass; }; }; }; }; }'.
//       Types of property 'b' are incompatible.
//         Type '{ c: { d: { e: { f: typeof OtherClass; }; }; }; }' is not assignable to type '{ c: { d: { e: { f: typeof ExampleClass; }; }; }; }'.
//           Types of property 'c' are incompatible.
//             Type '{ d: { e: { f: typeof OtherClass; }; }; }' is not assignable to type '{ d: { e: { f: typeof ExampleClass; }; }; }'.
//               Types of property 'd' are incompatible.
//                 Type '{ e: { f: typeof OtherClass; }; }' is not assignable to type '{ e: { f: typeof ExampleClass; }; }'.
//                   Types of property 'e' are incompatible.
//                     Type '{ f: typeof OtherClass; }' is not assignable to type '{ f: typeof ExampleClass; }'.
//                       Types of property 'f' are incompatible.
//                         Type 'typeof OtherClass' is not assignable to type 'typeof ExampleClass'.
//                           Type 'OtherClass' is not assignable to type 'ExampleClass'.
//                             Types of property 'state' are incompatible.
//                               Type 'number' is not assignable to type 'string'

// The nullish coalescing operator is an alternative to ||
// which returns the right-side expression if the left-side
// is null or undefined.

// In contrast, || uses falsy checks, meaning an empty
// string or the number 0 would be considered false.

// A good example for this feature is dealing with partial
// objects which have defaults when a key isn't passed in.

interface AppConfiguration {
  // Default: "(no name)"; empty string IS valid
  name: string;

  // Default: -1; 0 is valid
  items: number;

  // Default: true
  active: boolean;
}

function updateApp(config: Partial<AppConfiguration>) {
  // With null-coalescing operator
  config.name = config.name ?? "(no name)";
  config.items = config.items ?? -1;
  config.active = config.active ?? true;

  // Current solution
  config.name = typeof config.name === "string" ? config.name : "(no name)";
  config.items = typeof config.items === "number" ? config.items : -1;
  config.active = typeof config.active === "boolean" ? config.active : true;

  // Using || operator which could give bad data
  config.name = config.name || "(no name)"; // does not allow for "" input
  config.items = config.items || -1; // does not allow for 0 input
  config.active = config.active || true; // really bad, always true
}

// You can read more about nullish coalescing in the 3.7 blog post:
//
// https://devblogs.microsoft.com/typescript/announcing-typescript-3-7/

// Optional chaining reached TC39 Stage 3 consensus during
// 3.7's development. Optional Chaining allows you to write
// code which can immediately stop running expressions when
// it hits a null or undefined.

// Property Access

// Let's imagine we have an album where the artist, and the
// artists bio might not be present in the data. For example
// a compilation may not have a single artist.

type AlbumAPIResponse = {
  title: string;
  artist?: {
    name: string;
    bio?: string;
    previousAlbums?: string[];
  };
};

declare const album: AlbumAPIResponse;

// With optional chaining, you can write
// code like this:

const artistBio = album?.artist?.bio;

// Instead of:

const maybeArtistBio = album.artist && album.artist.bio;

// In this case ?. acts differently than the &&s since &&
// will act differently on "falsy" values (e.g. an empty string,
// 0, NaN, and, well, false).

// Optional chaining will only take null or undefined as
// a signal to stop and return an undefined.

// Optional Element Access

// Property access is via the . operator, the optional chaining
// also works with the [] operators when accessing elements.

const maybeArtistBioElement = album?.["artist"]?.["bio"];

const maybeFirstPreviousAlbum = album?.artist?.previousAlbums?.[0];

// Optional Calls

// When dealing with functions which may or may not exist at
// runtime, optional chaining supports only calling a function
// if it exists. This can replace code where you would traditionally
// write something like: if (func) func()

// For example here's an optional call to the callback from
// an API request:

const callUpdateMetadata = (metadata: any) => Promise.resolve(metadata); // Fake API call

const updateAlbumMetadata = async (metadata: any, callback?: () => void) => {
  await callUpdateMetadata(metadata);

  callback?.();
};

// You can read more about optional chaining in the 3.7 blog post:
//
// https://devblogs.microsoft.com/typescript/announcing-typescript-3-7/

// Given JavaScript's flexibility, it can be a good idea to add
// runtime checks to your code to validate your assumptions.

// These are typically called assertions (or invariants) and
// they are small functions which raise errors early when
// your variables don't match up to what you expect.

// Node comes with a function for doing this out of the box,
// it's called assert and it's available without an import.

// We're going to define our own though. This declares a
// function which asserts that the expression called
// value is true:
declare function assert(value: unknown): asserts value;

// Now we're use it to validate the type of an enum
declare const maybeStringOrNumber: string | number;
assert(typeof maybeStringOrNumber === "string");

// With TypeScript 3.7, the code flow analysis can use these
// types of functions to figure out what the code is. So,
// when you hover over the variable below - you can see that
// it has been narrowed from a string or number to
// just a string.

maybeStringOrNumber;

// You can use assertion functions to make guarantees of
// your types throughout your inferred code, for example
// TypeScript knows that this function will return a
// number without the need to add types to the parameter
// via the above assert declaration.

function multiply(x: any, y: any) {
  assert(typeof x === "number");
  assert(typeof y === "number");

  return x * y;
}

// Assertion functions are siblings to Type Guards
// example:type-guards except they affect the control flow
// when it continues through the function.

// For example, we can use assertion functions to narrow
// an enum down over time:

declare const oneOfFirstFiveNumbers: 1 | 2 | 3 | 4 | 5;

declare function isOdd(param: unknown): asserts param is 1 | 3 | 5;
declare function isBelowFour(param: unknown): asserts param is 1 | 2 | 3 | 4;

// This should cut down the enum to: 1 | 3 | 5

isOdd(oneOfFirstFiveNumbers);
oneOfFirstFiveNumbers;

// This will then cut the enum's possible states to: 1 | 3

isBelowFour(oneOfFirstFiveNumbers);
oneOfFirstFiveNumbers;

// This is a primer on some of the features of assertion functions
// in TypeScript 3.7 - you can find out more by reading the
// release notes:
//
// https://devblogs.microsoft.com/typescript/announcing-typescript-3-7/

// Choosing between using type vs interface is about the
// constraints in the features for each. With 3.7, one of
// the constrains on type but not in interface was removed.

// You can find out more about this in example:types-vs-interfaces

// It used to be that you could not refer to the type you
// are defining inside the type itself. This was a limit
// which didn't exist inside an interface, and could be worked
// around with a little work.

// For example, this is not feasible in 3.6:
type ValueOrArray<T> = T | Array<ValueOrArray<T>>;

// An implementation would have looked like this, by mixing
// the type with an interface.
type ValueOrArray2<T> = T | ArrayOfValueOrArray<T>;
interface ArrayOfValueOrArray<T> extends Array<ValueOrArray2<T>> { }

// This allows for a comprehensive definition of JSON,
// which works by referring to itself.

type Json = string | number | boolean | null | Json[] | { [key: string]: Json };

const exampleStatusJSON: Json = {
  available: true,
  username: "Jean-loup",
  room: {
    name: "Highcrest",
    // Cannot add functions into the Json type
    // update: () => {}
  },
};

// There's more to learn from the 3.7 beta release notes and its PR:
//
// https://devblogs.microsoft.com/typescript/announcing-typescript-3-7/
// https://github.com/microsoft/TypeScript/pull/33050

// New to 3.7 is a check inside if statements for
// when you accidentally use a function instead
// of the return value of a function.

// This only applies when the function is known
// to exist making the if statement always be true.

// Here is an example plugin interface, where there
// are optional and non-optional callbacks.

interface PluginSettings {
  pluginShouldLoad?: () => void;
  pluginIsActivated: () => void;
}

declare const plugin: PluginSettings;

// Because pluginShouldLoad could not exist, then
// the check is legitimate.

if (plugin.pluginShouldLoad) {
  // Do something when pluginShouldLoad exists.
}

// In 3.6 and below, this was not an error.

if (plugin.pluginIsActivated) {
  // Want to do something when the plugin is activated,
  // but instead of calling the method we used it as a
  // property.
}

// pluginIsActivated should always exist, but TypeScript
// still allows the check, because the method is called
// inside the if block.

if (plugin.pluginIsActivated) {
  plugin.pluginIsActivated();
}

// In previous versions of TypeScript, the checker would not
// verify that undeclared fields in a union conform to any indexed
// types in the union.

// You can learn about indexed types here: example:indexed-types

// For example, the IdentifierCache below indicates that any
// key on the object will be a number:

type IdentifierCache = { [key: string]: number };

// Meaning this will fail, because 'file_a' has a
// string value

const cacheWithString: IdentifierCache = { file_a: "12343" };

// However, when you put that into a union, then the
// validation check would not happen:

let userCache: IdentifierCache | { index: number };
userCache = { file_one: 5, file_two: "abc" };

// This is fixed, and there would be an error about
// 'file_two' from the compiler.

// This also takes into account when the key is a different
// type, for example: ([key: string] and [key: number])

type IdentifierResponseCache = { [key: number]: number };

let resultCache: IdentifierCache | IdentifierResponseCache;
resultCache = { file_one: "abc" };

// @ts-check

// The JSDoc support for TypeScript was extended to support
// the accessibility modifiers on class properties. There is:
//
// @public - the default, and what happens if you don't set one
// @private - the field can only be accessed in the same class
//            where the field is defined
// @protected - the field is accessible to the class where it is
//              defined and subclasses of that class
//

// This is a base class of Animal, it has both a private and
// protected field. Subclasses can access "this.isFast" but
// not "this.type".

// Outside of these the class, both of these fields are not
// visible and return a compiler error when // @ts-check is
// turned on:

class Animal {
  constructor(type) {
    /** @private */
    this.type = type;
    /** @protected */
    this.isFast = type === "cheetah";
  }

  makeNoise() {
    // Supposedly these are pretty much silent
    if (this.type === "bengal") {
      console.log("");
    } else {
      throw new Error("makeNoise was called on a base class");
    }
  }
}

class Cat extends Animal {
  constructor(type) {
    super(type || "housecat");
  }

  makeNoise() {
    console.log("meow");
  }

  runAway() {
    if (this.isFast) {
      console.log("Got away");
    } else {
      console.log("Did not make it");
    }
  }
}

class Cheetah extends Cat {
  constructor() {
    super("cheetah");
  }
}

class Bengal extends Cat {
  constructor() {
    super("bengal");
  }
}

const housecat = new Cat();
housecat.makeNoise();

// These are not available
housecat.type;
housecat.isFast;

// You can read more in the post
// https://devblogs.microsoft.com/typescript/announcing-typescript-3-8-beta/#jsdoc-modifiers

// TypeScripts ability to re-export got closer to supporting
// the additional cases available in ES2018
//
// JavaScript exports have the ability to elegantly
// re-export a part of a dependency:

export { ScriptTransformer } from "@jest/transform";

// When you wanted to export the full object, that
// becomes a little more verbose in previous versions
// of TypeScript:

import * as console from "@jest/console";
import * as reporters from "@jest/reporters";

export { console, reporters };

// With 3.8, TypeScript supports more of the export
// statement forms in the JavaScript specs, letting
// you write a single line to re-export a module

export * as jestConsole from "@jest/console";
export * as jestReporters from "@jest/reporters";

// 3.8 adds private fields, which are a way of declaring a class field to
// be unavailable outside of the containing class, including to subclasses.

// For example, the Person class below does not allow for anyone using an
// instance of the class to read  the firstName, lastName or prefix

class Person {
  #firstName: string;
  #lastName: string;
  #prefix: string;

  constructor(firstName: string, lastName: string, prefix: string) {
    this.#firstName = firstName;
    this.#lastName = lastName;
    this.#prefix = prefix;
  }

  greet() {
    // In iceland it is preferable to use a full name instead of [prefix] [lastname]
    // https://www.w3.org/International/questions/qa-personal-names#patronymic
    if (navigator.languages[0] === "is") {
      console.log(`Góðan dag, ${this.#firstName} ${this.#lastName}`);
    } else {
      console.log(`Hello, ${this.#prefix} ${this.#lastName}`);
    }
  }
}

let jeremy = new Person("Jeremy", "Bearimy", "Mr");

// You can't get to any of the private fields from outside that class:

// For example, this won't work:
console.log(jeremy.#lastName);

// Nor this:
console.log("Person's last name:", jeremy["#lastName"]);

// A common question we get is "Why would you use this over the 'private'
// keyword in a classfield?" - let's look by making a comparison to
// how it worked in TypeScript before 3.8:

class Dog {
  private _name: string;
  constructor(name: string) {
    this._name = name;
  }
}

let oby = new Dog("Oby");
// Won't let you access via dot notation
oby._name = "Spot";
// But TypeScript allows bracket notation as an escape clause
oby["_name"] = "Cherny";

// The TypeScript reference of private only exists at type-level
// which means that you can only trust it so far. With private fields
// soon to be a part of the JavaScript language, then you can make better
// guarantees about the visibility of your code.

// We don't plan on deprecating the `private` field keyword
// in TypeScript, so your existing code will continue to work, but now
// you can write code which is closer to the JavaScript language instead.

// You can learn more about class fields in the tc39 proposal
// https://github.com/tc39/proposal-class-fields/
// and the beta release notes:
// https://devblogs.microsoft.com/typescript/announcing-typescript-3-8-beta/#ecmascript-private-fields

// In 3.8 we added new syntax for importing types, which
// would be similar to users who have come from flow.

// 'import type' provides a way to declare a type only import
// which means you can be sure that the code will erased when
// converting to JavaScript in a very predictable way because
// it will always be removed!

// For example, this line will never add an import or require
import type { CSSProperties } from "react";

// Which is used here as a type
const style: CSSProperties = {
  textAlign: "center",
};

// This is in contrast to this import:
import * as React from "react";

// Which will be included in the JavaScript
export class Welcome extends React.Component {
  render() {
    return (
      <div style={style}>
        <h1>Hello, world</h1>
      </div>
    );
  }
}

// However, if the 'import' without types, only imports
// types - it could also be removed. If you look in the
// compiled JS output, this import is not included

import { FunctionComponent } from "react";

export const BetaNotice: FunctionComponent = () => {
  return <p>This page is still in beta</p>;
};

// This is called import elision, and it can be the source
// of confusion. The syntax 'import type' allows you to be
// specific about what you want in JavaScript.

// This is a small overview for one of the main use cases
// for 'import types' but there are more which you can read
// in the 3.8 release notes

// https://devblogs.microsoft.com/typescript/announcing-typescript-3-8-beta/#type-only-imports-exports

// In 4.0, we use control flow analysis to
// infer the potential type of a class property based on
// what values are set during the constructor.

class UserAccount {
  id; // Type is inferred as string | number
  constructor(isAdmin: boolean) {
    if (isAdmin) {
      this.id = "admin";
    } else {
      this.id = 0;
    }
  }
}

// In previous versions of TypeScript, `id` would
// have been classed as an `any`.

// In 4.0 the JSDoc tag @deprecated is added to the
// type system. You can use @deprecated anywhere
// you can use JSDoc currently.

interface AccountInfo {
  name: string;
  gender: string;

  /** @deprecated use gender field instead */
  sex: "male" | "female";
}

declare const userInfo: AccountInfo;
userInfo.sex;

// TypeScript will offer a non-blocking warning when a
// deprecated property is accessed, and editors like
// vscode will use show the deprecated info in places
// like intellisense, outlines and in your code.

// Logical Operators and Assignment are new features in
// JavaScript for 2020. These are a suite of new operators
// which edit a JavaScript object.

// Their goal is to re-use the concept of mathematical 
// operators (e.g. += -= *=) but with logic instead.

interface User {
  id?: number
  name: string
  location: {
      postalCode?: string
  }
}

function updateUser(user: User) {
  // This code can be replaced 
  if (!user.id) user.id = 1

  // Or this code:
  user.id = user.id || 1

  // With this code:
  user.id ||= 1
}

// The suites of operators can handle deeply nesting, which 
// can save on quite a lot of boilerplate code too.

declare const user: User
user.location.postalCode ||= "90210"

// There are three new operators: 
//
//   ||= shown above
//   &&= which uses 'and' logic instead of 'or'
//   ??= which builds on example:nullish-coalescing to offer a stricter
//       version of || which uses === instead

// For more info on the proposal, see:
// https://github.com/tc39/proposal-logical-assignment

// # Nullish Coalescing
//
// This is a new operator `??` which is meant to augment
// the common usage of `||` in the same way `===` augments `==`
// as a more strict form of equality.
//
// To understand it, let's look a how || works:

const response = {
  nullValue: null,
  headerText: "",
  animationDuration: 0,
  height: 400,
  showSplashScreen: false,
} as const;

const undefinedValue = response.undefinedValue || "some other default";
// This would be: 'some other default'

const nullValue = response.nullValue || "some other default";

// These two examples work similar in most languages. As a tool || is
// pretty good at defaulting things, but JavaScript's falsy checks
// can surprise you for some common values:

// Potentially unintended. '' is falsy, result: 'Hello, world!'
const headerText = response.headerText || "Hello, world!";

// Potentially unintended. 0 is falsy, result: 300
const animationDuration = response.animationDuration || 300;

// Potentially unintended. false is falsy, result: true
const showSplashScreen = response.showSplashScreen || true;

// When switching to use ?? instead, then === equality is used
// to compare the two sides:

const emptyHeaderText = response.headerText ?? "Hello, world!";
const zeroAnimationDuration = response.animationDuration ?? 300;
const skipSplashScreen = response.showSplashScreen ?? true;

// Tuples are arrays where the order is important to the type system,
// you can learn more about them in example:tuples

// In TypeScript 4.0, the type of a Tuple's gained the ability to give
// a name to the different parts of the array.

// For example, you used to write a Lat Long location via a tuple:

type OldLocation = [number, number]

const locations: OldLocation[] = [
    [40.7144, -74.006],
    [53.6458, -1.785]
]

// Knowing which is Latitude and Longitude is ambiguous, and so you
// would more likely have called it a LatLong tuple.

// With 4.0, you can write:

type NewLocation = [lat: number, long: number]

const newLocations: NewLocation[] = [
    [52.3702, 4.8952],
    [53.3498, -6.2603]
]

// The names now show up in the editor when you hover over
// the 0 and 1 at the end of the next line
const firstLat = newLocations[0][0]
const firstLong = newLocations[0][1]

// While that might seem a tad underwhelming, the main goal 
// is to ensure that information isn't lost when working
// with the type system. For example, when extracting
// parameters from a function using the Parameter 
// utility type:

function centerMap(lng: number, lat: number) { }

// In 4.0, this keeps lng and lat
type CenterMapParams = Parameters<typeof centerMap>

// In 3.9, this would look like
type OldCenterMapParams = [number, number]

// Making some of the more complex type manipulation lossy
// for the parameter information.

// Because JavaScript allows throwing any value, TypeScript
// does not support declaring the type of an error

try {
  // ..
} catch (e) { }

// Historically, this has meant that the `e` in the catch
// would default to any. This allowed for the freedom to
// arbitrarily access any property. With 4.0, we've loosened
// the restrictions on type assignment in the catch clause
// to allow both `any` and `unknown`.

// Same behavior with any:
try {
  // ..
} catch (e) {
  e.stack;
}

// Explicit behavior with unknown:

try {
  // ..
} catch (e: unknown) {
  // You cannot use `e` at all until the type
  // system learns what it is, for more info see:
  // example:unknown-and-never
  e.stack;

  if (e instanceof SyntaxError) {
    e.stack;
  }
}

// Variadic Tuples gives tuples the ability to handle the rest operator (...)
// to pass types through type checker in a way that works like generics.

// This is quite an advanced topic, so if you get lost do not worry too much.
// It builds on example:generic-functions and example:tuples

// To start off, here is a variadic tuple which will always prefix another
// tuple with a number:

type AddMax<T extends unknown[]> = [max: number, ...rest: T];
//          ^ Generic used to constrain the T
//                                                ^ ... used to indicate where to merge

// This can then be used for composition:
type MaxMin = AddMax<[min: number]>
type MaxMinDiameter = AddMax<[min: number, diameter: number]>

// The same can be used after the tuple:
type SuffixDIContext<T extends unknown[]> = [...first: T, context: any];
type DIContainer = SuffixDIContext<[param: string]>

// This mechanism can be combined with multiple input params. For example, this
